    """Validate a single document entry. Raises IngestError on malformed input."""
    if not isinstance(doc, dict):
        raise _IngestError(f"document at index {idx} must be a dict, got {type(doc).__name__}")
    if "document_id" not in doc:
        raise _IngestError(f"document at index {idx} missing 'document_id'")
    if "text" not in doc:
        raise _IngestError(f"document at index {idx} missing 'text'")


def ingest_documents(request: dict) -> dict:
    records = []
    documents = request.get("documents", [])
    for idx, doc in enumerate(documents):
        _validate_document(doc, idx)

        doc_id = doc["document_id"]
        text = doc["text"]
        incoming_meta = doc.get("metadata", {})

        # P2: has_frontmatter detection via upstream checks()
        has_fm = frontmatter.checks(text)

        # Parse with upstream python-frontmatter (P3: malformed fences preserved)
        metadata, content = frontmatter.parse(text)

        # Merge: incoming metadata as base, frontmatter metadata overrides
        merged_meta = {}
        if isinstance(incoming_meta, dict):
            merged_meta.update(incoming_meta)
        if isinstance(metadata, dict):
            merged_meta.update(metadata)

        # P1: project metadata JSON-safe (dates → ISO strings)
        safe_meta = _make_json_safe(merged_meta)

        records.append({
            "doc_id": doc_id,
            "has_frontmatter": has_fm,
            "metadata": safe_meta,
            "content": content,
        })

    return {"records": records}


